129 |     /// @notice `contribute()` in batch form.
130 |     ///         May not revert if any individual contribution fails.
131 |     /// @param args The arguments to pass to each `contribute()` call.
132 |     /// @return votingPowers The voting power received for each contribution.
133 |     function batchContribute(
134 |         BatchContributeArgs calldata args
135 |     ) external payable onlyDelegateCall returns (uint96[] memory votingPowers) {
136 |         uint256 numContributions = args.values.length;
137 |         votingPowers = new uint96[](numContributions);
138 | 
139 |         uint256 ethAvailable = msg.value;
140 |         for (uint256 i; i < numContributions; ++i) {
141 |             ethAvailable -= args.values[i];
142 | 
143 |             votingPowers[i] = _contribute(
144 |                 payable(msg.sender),
145 |                 args.delegate,
146 |                 args.values[i],
147 |                 args.gateDatas[i]
148 |             );
149 |         }
150 | 
151 |         // Refund any unused ETH.
152 |         if (ethAvailable > 0) payable(msg.sender).transfer(ethAvailable);
153 |     }
